from typing import *
from collections import *

def flatten(iterable):
    def flatten_recursive(item):
        if isinstance(item, list):
            return [flatten_recursive(x) for x in item]
        elif isinstance(item, tuple):
            return tuple(flatten_recursive(x) for x in item)
        elif isinstance(item, dict):
            return [flatten_recursive(k) + [v] for k, v in item.items()]
        return [item]

    return flatten_recursive(iterable)

# Test the function with provided data points
