    for item in iterable:
        if isinstance(item, list):
            ret.extend(flatten(item))
        elif isinstance(item, int):
            ret.append(item)
        elif isinstance(item, float):
            ret.append(item)
        elif isinstance(item, str):
            ret.append(item)
        else:
            raise ValueError(f"Unsupported type: {type(item)}")
    return ret
